804	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
805	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
806	     *
807	     * @return the owner's check digit, or {@code null} when it has no customer code
808	     */
809	    @Transient
810	    public Integer getCheckDigit() {
811	        if (this.customerCode == null) {
812	            return null;
813	        }
814	        return luhnCheckDigit(this.customerCode);
815	    }
