817	    /**
818	     * Computes the single Luhn check digit (0-9) over the digits contained in a string: reading from
819	     * the right, every second digit is doubled (subtracting 9 when the result exceeds 9), the digits
820	     * are summed and the check digit is the amount that rounds the sum up to the next multiple of ten.
821	     * Non-digit characters are skipped, so a code mixing letters and digits contributes only its
822	     * digits. This is the single definition of the Luhn check digit, shared by every value that
823	     * carries one (see {@link #getCheckDigit()}).
824	     *
825	     * @param code the string whose digits the check digit is computed over
826	     * @return the Luhn check digit (0-9) of {@code code}
827	     */
828	    public static int luhnCheckDigit(String code) {
829	        int sum = 0;
830	        boolean dbl = true;
831	        for (int i = code.length() - 1; i >= 0; i--) {
832	            char c = code.charAt(i);
833	            if (c < '0' || c > '9') {
834	                continue;
835	            }
836	            int d = c - '0';
837	            if (dbl) {
838	                d *= 2;
839	                if (d > 9) {
840	                    d -= 9;
841	                }
842	            }
843	            sum += d;
844	            dbl = !dbl;
845	        }
846	        return (10 - (sum % 10)) % 10;
847	    }
