849	    /**
850	     * Returns this owner's age band, derived from {@code birthDate} computed against
851	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
852	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
853	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
854	     * band cannot be derived. This is the single definition of an owner's age band.
855	     *
856	     * @return the owner's age band, or {@code null} when it cannot be derived
857	     */
858	    @Transient
859	    public String getAgeBand() {
860	        if (this.birthDate == null || this.registrationDate == null) {
861	            return null;
862	        }
863	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
864	        if (age < 18) {
865	            return "MINOR";
866	        }
867	        if (age < 65) {
868	            return "ADULT";
869	        }
870	        return "SENIOR";
871	    }
