910	     * Return the Pet with the given name, or null if none found for this Owner.
911	     *
912	     * @param name to test
913	     * @return true if pet name is already in use
914	     */
915	    public Pet getPet(String name, boolean ignoreNew) {
916	        name = name.toLowerCase();
917	        for (Pet pet : getPetsInternal()) {
918	            if (!ignoreNew || !pet.isNew()) {
919	                String compName = pet.getName();
920	                compName = compName.toLowerCase();
921	                if (compName.equals(name)) {
