446	    /**
447	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
448	     * The address is normalized in place (so a required-field check that follows rejects an
449	     * address blank after normalization), the required fields are checked, the telephone and
450	     * email are normalized in place, and the resulting owner is rejected when its derived
451	     * identity key already belongs to another owner. Each rule
452	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
453	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
454	     * to be mapped and saved.
455	     *
456	     * @param ownerFieldsDto the submitted owner fields, normalized in place
457	     */
458	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
459	        applyAddress(ownerFieldsDto);
460	        validateRequiredFields(ownerFieldsDto);
461	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
462	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
463	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
464	        rejectDuplicateIdentity(ownerFieldsDto);
465	        rejectCityAtCapacity(ownerFieldsDto.getCity());
466	        rejectDailyLimitExceeded(registrationDate);
467	    }
