469	    /**
470	     * Applies an owner's address to the submitted fields, normalizing it in place into the
471	     * canonical form stored and returned for the owner. This is the single intake step that owns
472	     * how a submitted address becomes an owner's stored address: it delegates every transform to
473	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
474	     * the results back onto {@code ownerFieldsDto}.
475	     *
476	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
477	     * is present the two structured lines are normalized in place and the flat {@code address} is
478	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
479	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
480	     * every rule that later reads {@code address} sees the structured value. When no structured
481	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
482	     * backward compatibility.
483	     *
484	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
485	     * blank after normalization in either form is rejected by the required-field check that
486	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
487	     * list of named intake steps and gives address handling one place to grow.
488	     *
489	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
490	     */
491	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
492	        String line1 = ownerFieldsDto.getAddressLine1();
493	        if (line1 != null && !line1.isBlank()) {
494	            String normalizedLine1 = normalizeAddress(line1);
495	            ownerFieldsDto.setAddressLine1(normalizedLine1);
496	            String line2 = ownerFieldsDto.getAddressLine2();
497	            if (line2 != null && !line2.isBlank()) {
498	                String normalizedLine2 = normalizeAddress(line2);
499	                ownerFieldsDto.setAddressLine2(normalizedLine2);
500	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
501	            } else {
502	                ownerFieldsDto.setAddressLine2(null);
503	                ownerFieldsDto.setAddress(normalizedLine1);
504	            }
505	        } else {
506	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
507	        }
508	    }
