510	    /**
511	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
512	     * falls on a business day. The date supplied on the request is used when present, otherwise the
513	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
514	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
515	     * is left unchanged. This single adjusted date
516	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
517	     * membership number's year segment, the per-day create limit) is computed against.
518	     *
519	     * A supplied registration date later than the server's current date is rejected with an
520	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
521	     *
522	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
523	     * @return the effective registration date rolled forward to the next business day
524	     */
525	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
526	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
527	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
528	            throw new InvalidFieldsException(List.of("registrationDate"));
529	        }
530	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
531	        return toBusinessDay(effective);
532	    }
533	
534	    /**
535	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
536	     * advanced, along with weekends, until it reaches the next non-holiday business day.
537	     */
538	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
539	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
540	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
541	        LocalDate.parse("2026-12-28"));
542	
543	    /**
544	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
545	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
546	     * date already on such a business day is returned unchanged.
547	     *
548	     * @param date the date to adjust
549	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
550	     */
551	    private LocalDate toBusinessDay(LocalDate date) {
552	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
553	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
554	                || PUBLIC_HOLIDAYS.contains(date)) {
555	            date = date.plusDays(1);
556	        }
557	        return date;
558	    }
