560	    /**
561	     * The maximum number of owners that may be created on a single day. Once this many owners
562	     * already carry today's {@code registrationDate}, no further owner may be created today.
563	     */
564	    private static final long DAILY_OWNER_LIMIT = 100L;
565	
566	    /**
567	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
568	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
569	     * date the new owner would be stored with, so owners are capped per business day. When the limit
570	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
571	     * advice renders as a 429 Too Many Requests response.
572	     *
573	     * @param registrationDate the adjusted business-day registration date of the owner being created
574	     */
575	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
576	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
577	            throw new DailyOwnerLimitExceededException(registrationDate);
578	        }
579	    }
580	
581	    /**
582	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
583	     * given date. This is the single definition of the per-day owner count, shared by the per-day
584	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
585	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
586	     *
587	     * @param registrationDate the adjusted business-day registration date to count owners against
588	     * @return the number of existing owners carrying that registration date
589	     */
590	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
591	        return this.clinicService.findAllOwners().stream()
592	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
593	            .count();
594	    }
595	
596	    /**
597	     * The number of owners that may carry a single day's {@code registrationDate} before that day
598	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
599	     * the create and read responses report {@code bulkSignupWarning} true for that date.
600	     */
601	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
602	
603	    /**
604	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
605	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
606	     * count is taken against the same adjusted date owners are stored with, mirroring the
607	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
608	     *
609	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
610	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
611	     */
612	    private boolean bulkSignupWarning(LocalDate registrationDate) {
613	        if (registrationDate == null) {
614	            return false;
615	        }
616	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
617	    }
