619	    /**
620	     * The maximum number of owners a single city may hold. Once a city already contains this
621	     * many owners, no further owner may be created in it.
622	     */
623	    private static final long CITY_OWNER_CAPACITY = 50L;
624	
625	    /**
626	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
627	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
628	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
629	     * which the exception advice renders as a 409 Conflict response.
630	     *
631	     * @param city the city of the owner being created
632	     */
633	    private void rejectCityAtCapacity(String city) {
634	        if (countOwnersInCity(city) >= CITY_OWNER_CAPACITY) {
635	            throw new CityCapacityExceededException(city);
636	        }
637	    }
638	
639	    /**
640	     * Counts the existing owners whose {@code city} equals the given city, compared
641	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
642	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
643	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
644	     *
645	     * @param city the city to count owners against
646	     * @return the number of existing owners whose city matches
647	     */
648	    private long countOwnersInCity(String city) {
649	        return this.clinicService.findAllOwners().stream()
650	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
651	            .count();
652	    }
653	
654	    /**
655	     * The number of owners a city must already contain before it is flagged as approaching its
656	     * capacity limit. Once a city holds at least this many owners (but is not yet at
657	     * {@link #CITY_OWNER_CAPACITY}), the create and read responses report {@code capacityWarning}
658	     * true for owners in that city.
659	     */
660	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
661	
662	    /**
663	     * Reports whether the given city is approaching its capacity limit, i.e. whether it already
664	     * contains between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_CAPACITY}
665	     * minus one owners (40 to 49) inclusive. The count is taken the same way the hard rejection
666	     * counts a city's owners ({@link #countOwnersInCity(String)}). A {@code null} city never warns.
667	     *
668	     * @param city the city to test, or {@code null}
669	     * @return {@code true} when the city holds 40 to 49 owners, otherwise {@code false}
670	     */
671	    private boolean capacityWarning(String city) {
672	        if (city == null) {
673	            return false;
674	        }
675	        long count = countOwnersInCity(city);
676	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_CAPACITY;
677	    }
