679	    /**
680	     * Builds the customer code assigned to a newly created owner. The code is formatted as
681	     * {@code '<REGION>-<HASH8>'}, joining the owner's region code (see {@link Owner#getRegionCode()},
682	     * rendered {@code 'UNKNOWN'} when the owner has no known region) to its identity hash (see
683	     * {@link Owner#getIdentityHash()}, the first 8 upper-case hex characters of the SHA-256 digest
684	     * over the owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}),
685	     * then de-duplicated against existing owners (see {@link #deduplicateCustomerCode(String)}). The
686	     * composed base carries no sequence number, so two owners sharing a region, telephone and last
687	     * name resolve to the same base code and are separated only by de-duplication.
688	     *
689	     * @param owner the owner being created, whose fields the code is derived from
690	     * @return the formatted customer code
691	     */
692	    private String customerCodeFor(Owner owner) {
693	        return deduplicateCustomerCode(owner.getRegionCode() + "-" + owner.getIdentityHash());
694	    }
695	
696	    /**
697	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
698	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
699	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
700	     *
701	     * @param baseCode the customer code computed for the owner being created
702	     * @return the base code when it is already unique, otherwise the de-duplicated code
703	     */
704	    private String deduplicateCustomerCode(String baseCode) {
705	        Set<String> existing = this.clinicService.findAllOwners().stream()
706	            .map(Owner::getCustomerCode)
707	            .filter(Objects::nonNull)
708	            .collect(Collectors.toSet());
709	        if (!existing.contains(baseCode)) {
710	            return baseCode;
711	        }
712	        int n = 2;
713	        while (existing.contains(baseCode + "-" + n)) {
714	            n++;
715	        }
716	        return baseCode + "-" + n;
717	    }
718	
719	    /**
720	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
721	     * with the owner being created, compared case-insensitively. The count is taken before the
722	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
723	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
724	     *
725	     * @param firstName the first name of the owner being created
726	     * @param lastName the last name of the owner being created
727	     * @return the number of pre-existing owners sharing the same first and last name
728	     */
729	    private int countNamesakes(String firstName, String lastName) {
730	        return (int) this.clinicService.findAllOwners().stream()
731	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
732	                && lastName.equalsIgnoreCase(existing.getLastName()))
733	            .count();
734	    }
