794	    /**
795	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
796	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
797	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
798	     * the names of every offending field, which the exception advice renders as a 400 response
799	     * with an {@code errors} array.
800	     *
801	     * @param ownerFieldsDto the submitted owner fields
802	     */
803	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
804	        List<String> missing = new ArrayList<>();
805	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
806	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
807	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
808	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
809	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
810	        if (!missing.isEmpty()) {
811	            throw new RequiredFieldsMissingException(missing);
812	        }
813	    }
814	
815	    private void addIfBlank(List<String> missing, String fieldName, String value) {
816	        if (value == null || value.isBlank()) {
817	            missing.add(fieldName);
818	        }
819	    }
820	
821	    /**
822	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
823	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
824	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
825	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
826	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
827	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
828	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
829	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
830	     *
831	     * @param telephone the submitted telephone value
832	     * @return the normalized E.164 telephone
833	     */
834	    private String normalizeTelephone(String telephone) {
835	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
836	        String e164;
837	        if (cleaned.startsWith("+")) {
838	            e164 = "+" + cleaned.substring(1);
839	        } else {
840	            String national = cleaned;
841	            if (national.startsWith("0")) {
842	                national = national.substring(1);
843	            }
844	            e164 = "+61" + national;
845	        }
846	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
847	            throw new InvalidFieldsException(List.of("telephone"));
848	        }
849	        validateNationalNumberLength(e164);
850	        return e164;
851	    }
852	
853	    /**
854	     * Validates the national-number length of an already syntactically valid E.164 telephone
855	     * against its country code. When the number carries a country code this application recognizes
856	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
857	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
858	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
859	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
860	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
861	     * that is not recognized carries no per-country length rule and is left to the general
862	     * 8-to-15-digit E.164 check.
863	     *
864	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
865	     */
866	    private void validateNationalNumberLength(String e164) {
867	        String countryCode = Owner.countryCodeOf(e164);
868	        if (countryCode == null) {
869	            return;
870	        }
871	        int nationalLength = e164.length() - 1 - countryCode.length();
872	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
873	            throw new InvalidFieldsException(List.of("telephone"));
874	        }
875	    }
876	
877	    /**
878	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
879	     * and a domain containing at least one dot, none of the parts holding whitespace or a
880	     * second {@code @}.
881	     */
882	    private static final java.util.regex.Pattern EMAIL_PATTERN =
883	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
884	
885	    /**
886	     * Disposable email domains an owner may not register with. An email whose domain (compared
887	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
888	     */
889	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
890	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
891	
892	    /**
893	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
894	     * accepted and returned unchanged. When present it must be a syntactically valid address
895	     * whose domain is not on the disposable-domain blocklist (see
896	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
897	     * present but syntactically invalid or on a disposable domain an
898	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
899	     * response naming the {@code email} field.
900	     *
901	     * @param email the submitted email value, or {@code null} when omitted
902	     * @return the lower-cased email, or {@code null} when none was supplied
903	     */
904	    private String normalizeEmail(String email) {
905	        if (email == null) {
906	            return null;
907	        }
908	        String trimmed = email.trim();
909	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
910	            throw new InvalidFieldsException(List.of("email"));
911	        }
912	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
913	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
914	            throw new InvalidFieldsException(List.of("email"));
915	        }
916	        return canonicalEmail(trimmed);
917	    }
918	
919	    /**
920	     * Reduces an email to the canonical form used both to store it and to compare it against
921	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
922	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
923	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
924	     * value read back off an existing owner without risk of rejecting it. This is the single
925	     * definition of email identity: two emails denote the same address exactly when they
926	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
927	     * an email already on an existing owner can be compared for equality after both pass through
928	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
929	     *
930	     * @param email the email to canonicalize, or {@code null} when none was supplied
931	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
932	     */
933	    private String canonicalEmail(String email) {
934	        if (email == null) {
935	            return null;
936	        }
937	        return email.trim().toLowerCase(java.util.Locale.ROOT);
938	    }
939	
940	    /**
941	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
942	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
943	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
944	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
945	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
946	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
947	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
948	     * 400 response naming the {@code postcode} field.
949	     *
950	     * @param postcode the submitted postcode, or {@code null} when omitted
951	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
952	     */
953	    private void validatePostcode(String postcode, String city) {
954	        if (postcode == null) {
955	            return;
956	        }
957	        if (!postcode.matches("^[0-9]{4}$")) {
958	            throw new InvalidFieldsException(List.of("postcode"));
959	        }
960	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
961	        if (range != null) {
962	            int value = Integer.parseInt(postcode);
963	            if (value < range[0] || value > range[1]) {
964	                throw new InvalidFieldsException(List.of("postcode"));
965	            }
966	        }
967	    }
968	
969	    /**
970	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
971	     * identity is its single derived identity key (see
972	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
973	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
974	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
975	     * owner carries the same identity key. The email-domain blocklist has already been applied when
976	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
977	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
978	     * name and postcode) but carry different telephones now have distinct identity keys and are not
979	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
980	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
981	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
982	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
983	     * deliberate household member and bypasses this block.
984	     *
985	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
986	     */
987	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
988	        if (sharesHousehold(ownerFieldsDto)) {
989	            return;
990	        }
991	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
992	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
993	        boolean taken = this.clinicService.findAllOwners().stream()
994	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
995	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
996	        if (taken) {
997	            throw new DuplicateIdentityException(identityKey);
998	        }
999	    }
1000	
1001	    /**
1002	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
1003	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
1004	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
1005	     * resolves to the same stable value automatically, without any explicit linking. An owner without
1006	     * a postcode belongs to no shared household and is left without a household identifier.
1007	     *
1008	     * @param owner the newly created owner, mutated in place with its household identifier
1009	     */
1010	    private void assignHousehold(Owner owner) {
1011	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
1012	    }
1013	
1014	    /**
1015	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
1016	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
1017	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
1018	     * every rule that treats a declared household member differently from an independent owner.
1019	     *
1020	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
1021	     * @return {@code true} when the request opted into sharing a household
1022	     */
1023	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
1024	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
1025	    }
1026	
1027	    /**
1028	     * Derives the stable {@code householdId} shared by every owner in the household identified by
1029	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
1030	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
1031	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
1032	     * postcode — regardless of creation order or address — resolve to the same identifier
1033	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
1034	     * returned.
1035	     *
1036	     * @param lastName the household's last name
1037	     * @param postcode the household's postcode, or {@code null} when the owner has none
1038	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
1039	     */
1040	    private String householdIdFor(String lastName, String postcode) {
1041	        if (postcode == null) {
1042	            return null;
1043	        }
1044	        return shaHex(householdKey(lastName, postcode), 12);
1045	    }
1046	
1047	    /**
1048	     * Builds the canonical household key that identifies the household a {@code lastName} and
1049	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
1050	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
1051	     * owner fields make up a household and how they are normalized;
1052	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
1053	     * owners in the same household resolve to the same key and therefore the same identifier.
1054	     *
1055	     * @param lastName the household's last name
1056	     * @param postcode the household's postcode
1057	     * @return the normalized household key
1058	     */
1059	    private String householdKey(String lastName, String postcode) {
1060	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
1061	    }
1062	
1063	    /**
1064	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
1065	     * string, the form used by the derived owner codes (for example the customer code and household
1066	     * identifier). Delegates to {@link Owner#shaHexPrefix(String, int)}, the single definition of the
1067	     * truncated upper-case hex derivation, so {@code hexChars} characters cover the leading
1068	     * {@code ceil(hexChars / 2)} bytes of the digest.
1069	     *
1070	     * @param input the string to hash
1071	     * @param hexChars the number of leading upper-case hex characters to return
1072	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
1073	     */
1074	    private String shaHex(String input, int hexChars) {
1075	        return Owner.shaHexPrefix(input, hexChars);
1076	    }
1077	
1078	    /**
1079	     * Returns the owners that belong to the household identified by the given {@code householdId},
1080	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
1081	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
1082	     * filters them out itself. The owners are taken from the current set, so after a create the
1083	     * result includes the newly persisted owner. An owner without a household (a {@code null}
1084	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
1085	     * definition of a household's members, shared by every rule that reasons about the owners
1086	     * sharing a household (the household-duplicate block and the household member count).
1087	     *
1088	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1089	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1090	     */
1091	    private List<Owner> householdMembers(String householdId) {
1092	        if (householdId == null) {
1093	            return List.of();
1094	        }
1095	        return this.clinicService.findAllOwners().stream()
1096	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1097	            .collect(Collectors.toList());
1098	    }
1099	
1100	    /**
1101	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1102	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1103	     * is taken against the current set of owners, so after a create it reflects the household's size
1104	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1105	     * belongs to no shared household and yields {@code 0}.
1106	     *
1107	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1108	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1109	     */
1110	    private int countHouseholdMembers(String householdId) {
1111	        return householdMembers(householdId).size();
1112	    }
1113	
1114	    /**
1115	     * Stamps an owner with its household member count, the number of owners sharing its household
1116	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1117	     * household size (its membership factor and level) reads a populated count rather than the
1118	     * unstamped default. This is the single definition of hydrating an owner with its household
1119	     * member count, shared by the create and read paths that render an owner's derived values.
1120	     *
1121	     * @param owner the owner to stamp, mutated in place with its household member count
1122	     */
1123	    private void applyHouseholdMemberCount(Owner owner) {
1124	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1125	    }
1126	
1127	    /**
1128	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1129	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1130	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1131	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1132	     * reads a populated count, mirroring how the create and read paths render a member's derived
1133	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1134	     * members already in the household. When the owner joins an empty household — no household
1135	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1136	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1137	     *
1138	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1139	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1140	     */
1141	    private Integer householdMembershipLevelCap(String householdId) {
1142	        java.util.OptionalInt max = householdMembers(householdId).stream()
1143	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1144	            .peek(this::applyHouseholdMemberCount)
1145	            .mapToInt(Owner::getMembershipLevel)
1146	            .max();
1147	        return max.isPresent() ? max.getAsInt() + 1 : null;
1148	    }
1149	
1150	    /**
1151	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1152	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1153	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1154	     *
1155	     * @param value the value to collapse, or {@code null}
1156	     * @return the whitespace-collapsed value, never {@code null}
1157	     */
1158	    private String collapseWhitespace(String value) {
1159	        if (value == null) {
1160	            return "";
1161	        }
1162	        return value.trim().replaceAll("\\s+", " ");
1163	    }
1164	
1165	    /**
1166	     * Common street-type abbreviations expanded during address normalization, keyed by their
1167	     * upper-cased token.
1168	     */
1169	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1170	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1171	
1172	    /**
1173	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1174	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1175	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1176	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1177	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1178	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1179	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1180	     * everywhere an address is stored or compared.
1181	     *
1182	     * @param address the submitted address value, or {@code null}
1183	     * @return the normalized address, never {@code null}
1184	     */
1185	    private String normalizeAddress(String address) {
1186	        if (address == null) {
1187	            return "";
1188	        }
1189	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1190	        if (collapsed.isEmpty()) {
1191	            return "";
1192	        }
1193	        String[] tokens = collapsed.split(" ");
1194	        StringBuilder sb = new StringBuilder(collapsed.length());
1195	        for (int i = 0; i < tokens.length; i++) {
1196	            if (i > 0) {
1197	                sb.append(' ');
1198	            }
1199	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1200	        }
1201	        return sb.toString();
1202	    }
1203	}
